<?php use app\modules\housing\models\{Meter,MaintenanceRequest};use yii\helpers\Html;$this->title='ค่าใช้จ่ายและมิเตอร์';$this->beginBlock('page-title');?><?=Html::encode($this->title)?><?php $this->endBlock();$this->beginBlock('page-action');?><?=$this->render('../_menu',['active'=>'utility'])?><?php $this->endBlock();$tabs=['readings'=>'จดเลขมิเตอร์','meters'=>'ทะเบียนมิเตอร์','rates'=>'อัตราค่าใช้จ่าย'];?>
<div class="container-fluid py-3"><div class="d-flex flex-wrap gap-2 mb-3"><?=Html::a('ลงค่าใช้จ่ายรายเดือน',['monthly'],['class'=>'btn btn-primary'])?> <?=Html::a('ตั้งค่าประเภทค่าใช้จ่าย',['charge-types'],['class'=>'btn btn-outline-secondary'])?></div><div class="card border-0 shadow-sm"><div class="card-header bg-white d-flex flex-wrap justify-content-between gap-2"><ul class="nav nav-pills"><?php foreach($tabs as $k=>$v):?><li class="nav-item"><?=Html::a($v,['index','section'=>$k],['class'=>'nav-link '.($section===$k?'active':'')])?></li><?php endforeach;?></ul><?=Html::a('<i class="bi bi-plus-lg"></i> เพิ่มข้อมูล',['create-'.($section==='rates'?'rate':($section==='meters'?'meter':'reading'))],['class'=>'btn btn-primary open-modal','data-size'=>'modal-xl'])?></div><div class="table-responsive"><table class="table table-hover align-middle mb-0">
<?php if($section==='rates'):?><thead><tr><th>ประเภท</th><th>ขอบเขต</th><th>วิธีคิด</th><th class="text-end">อัตรา</th><th>เริ่มใช้</th><th></th></tr></thead><tbody><?php foreach($rates as $m):?><tr><td><?=$m->chargeType->name??'—'?></td><td><?=Html::encode($m->unit->name??$m->building->name??'ทุกแห่ง')?></td><td><?=$m->calculation_type==='flat'?'เหมาจ่าย':'ต่อหน่วย'?></td><td class="text-end"><?=Yii::$app->formatter->asDecimal($m->rate,2)?></td><td><?=$m->effective_from?></td><td><?=Html::a('แก้ไข',['update-rate','id'=>$m->id],['class'=>'btn btn-sm btn-outline-primary open-modal'])?></td></tr><?php endforeach;?></tbody>
<?php elseif($section==='meters'):?><thead><tr><th>มิเตอร์</th><th>ประเภท</th><th>บ้านพัก/ห้อง</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach($meters as $m):?><tr><td><strong><?=Html::encode($m->name)?></strong><div class="small text-body-secondary"><?=Html::encode($m->meter_no?:'ไม่ระบุเลข')?></div></td><td><?=Meter::typeOptions()[$m->meter_type]??$m->meter_type?></td><td><?=Html::encode($m->unit->name??$m->building->name??'—')?></td><td><?=$m->status==='active'?'ใช้งาน':'งดใช้งาน'?></td><td><?=Html::a('แก้ไข',['update-meter','id'=>$m->id],['class'=>'btn btn-sm btn-outline-primary open-modal'])?></td></tr><?php endforeach;?></tbody>
<?php else:?><thead><tr><th>วันที่</th><th>มิเตอร์</th><th class="text-end">ครั้งก่อน</th><th class="text-end">ปัจจุบัน</th><th class="text-end">หน่วยใช้</th><th class="text-end">อัตรา</th><th class="text-end">ยอดเงิน</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach($readings as $m):?><tr><td><?=$m->reading_date?></td><td><?=Html::encode($m->meter->name??'—')?></td><td class="text-end"><?=$m->previous_value?></td><td class="text-end"><?=$m->current_value?></td><td class="text-end fw-semibold"><?=$m->usage_value?></td><td class="text-end"><?=$m->unit_rate?></td><td class="text-end"><?=Yii::$app->formatter->asDecimal($m->amount,2)?></td><td><?=$m->status==='confirmed'?'<span class="badge bg-success-subtle text-success-emphasis">ยืนยันแล้ว</span>':'<span class="badge bg-warning-subtle text-warning-emphasis">ฉบับร่าง</span>'?></td><td><?php if($m->status==='draft'):?><?=Html::a('แก้ไข',['update-reading','id'=>$m->id],['class'=>'btn btn-sm btn-outline-primary open-modal'])?> <?=Html::a('ยืนยัน',['confirm-reading','id'=>$m->id],['class'=>'btn btn-sm btn-success','data-method'=>'post','data-confirm'=>'ยืนยันเลขมิเตอร์แล้วจะไม่สามารถแก้ไขได้'])?><?php endif;?></td></tr><?php endforeach;?></tbody><?php endif;?>
</table></div><?php $items=$section==='rates'?$rates:($section==='meters'?$meters:$readings);if(!$items):?><div class="text-center py-5"><i class="bi bi-calculator"></i><div class="fw-semibold mt-2">ยังไม่มีข้อมูล</div><div class="small text-body-secondary">กด “เพิ่มข้อมูล” เพื่อเริ่มต้น</div></div><?php endif;?></div></div>
